SELECT 
FROM environment_entry
WHERE user_id = #{userId}
  AND deleted = 0
  AND (
    NOT EXISTS (
      SELECT 1 FROM environment_entry_project ep
      WHERE ep.environment_id = environment_entry.id
    )
    OR EXISTS (
      SELECT 1 FROM environment_entry_project ep
      WHERE ep.environment_id = environment_entry.id
        AND ep.project_id = #{projectId}
    )
  )
ORDER BY project_id IS NOT NULL, item_key, id

SELECT COUNT(*)
FROM environment_entry
WHERE deleted = 0
  AND item_key = #{itemKey}

    AND id != #{excludingId}

SELECT COUNT(*)
FROM environment_entry
WHERE user_id = #{userId}
  AND deleted = 0
  AND item_key = #{itemKey}

    AND id != #{excludingId}

SELECT environment_id, project_id FROM environment_entry_project WHERE environment_id IN
#{environmentId}
ORDER BY environment_id, project_id
